INSERT INTO battle_questions (id, battle_id, question_text, question_type, options, correct_answer, explanation, points, display_order, created_at, updated_at) VALUES
    ('ae15ff8d-bd25-5a06-b54f-bc9107ae2873', '00000000-0000-0000-0000-00000b000001', $q$Which Thread method actually creates a new thread of execution?$q$, 'MCQ', $o$["start()", "run()", "execute()", "begin()"]$o$, 'start()', $e$start() asks the JVM to create a new thread, which then calls run(). Calling run() directly is an ordinary method call on the current thread.$e$, 10, 1, now(), now()),
    ('8b76ec2a-0638-562b-9a35-87dc8a0d99f5', '00000000-0000-0000-0000-00000b000001', $q$What does this program print? (Lines are shown separated by " / ".)

public class Main {
    public static void main(String[] args) throws Exception {
        Thread t = new Thread(() -> System.out.println(Thread.currentThread().getName()));
        t.run();
    }
}
$q$, 'PREDICT_OUTPUT', $o$["main", "Thread-0", "Nothing is printed", "Compilation error"]$o$, 'main', $e$run() was called directly, so the lambda executes on the main thread and prints "main".$e$, 10, 2, now(), now()),
    ('5d8fb1d1-9f6a-5821-9aef-35ef1126c4a6', '00000000-0000-0000-0000-00000b000001', $q$The main thread must read a result computed by a worker thread only after the worker has finished. Which approach is correct?$q$, 'CHOOSE_APPROACH', $o$["Call worker.join() before reading the result", "Call Thread.sleep(1000) and hope it is done", "Call worker.run() from a second worker", "Mark the result variable private"]$o$, 'Call worker.join() before reading the result', $e$join() blocks until the worker terminates and also establishes a happens-before edge, so the result is safely visible.$e$, 10, 3, now(), now()),
    ('fbcb28d8-d6cb-5f54-ab2d-5fd7fc7e40a3', '00000000-0000-0000-0000-00000b000001', $q$What happens if start() is called twice on the same Thread object?$q$, 'MCQ', $o$["IllegalThreadStateException is thrown", "A second thread is started", "The first thread restarts", "Nothing, the second call is ignored"]$o$, 'IllegalThreadStateException is thrown', $e$A Thread can be started only once; a second start() throws IllegalThreadStateException.$e$, 10, 4, now(), now()),
    ('d63dc023-96eb-50df-8d57-5b3ed4741103', '00000000-0000-0000-0000-00000b000001', $q$What does this program print? (Lines are shown separated by " / ".)

public class Main {
    public static void main(String[] args) throws Exception {
        Thread t = new Thread(() -> System.out.println("work"));
        t.start();
        t.join();
        System.out.println("done");
    }
}
$q$, 'PREDICT_OUTPUT', $o$["work / done", "done / work", "work", "done"]$o$, 'work / done', $e$join() makes main wait for the worker, so "work" is always printed before "done".$e$, 10, 5, now(), now()),
    ('bfc6a156-6d61-54a7-9820-eab234fae912', '00000000-0000-0000-0000-00000b000002', $q$Which situation makes a variable a "shared resource" problem?$q$, 'MCQ', $o$["Several threads read and write it without coordination", "It is declared final", "It is a local variable inside a method", "It is only read by one thread"]$o$, 'Several threads read and write it without coordination', $e$Shared mutable state accessed by multiple threads needs coordination; final fields and thread-confined locals do not.$e$, 10, 1, now(), now()),
    ('a9b4471f-191f-5b01-8f70-acd5618e0e35', '00000000-0000-0000-0000-00000b000002', $q$What does this program print? (Lines are shown separated by " / ".)

import java.util.concurrent.atomic.AtomicInteger;

public class Main {
    public static void main(String[] args) throws Exception {
        AtomicInteger counter = new AtomicInteger();
        Runnable task = () -> {
            for (int i = 0; i < 1000; i++) counter.incrementAndGet();
        };
        Thread a = new Thread(task);
        Thread b = new Thread(task);
        a.start();
        b.start();
        a.join();
        b.join();
        System.out.println(counter.get());
    }
}
$q$, 'PREDICT_OUTPUT', $o$["2000", "Less than 2000, varies per run", "1000", "Compilation error"]$o$, '2000', $e$incrementAndGet() is atomic, so none of the 2 x 1000 increments are lost.$e$, 10, 2, now(), now()),
    ('ec0340d0-213a-5907-adad-bb0abb749f51', '00000000-0000-0000-0000-00000b000002', $q$Many threads increment one shared counter. What is the simplest thread-safe fix without writing explicit locks?$q$, 'CHOOSE_APPROACH', $o$["Use an AtomicInteger", "Make the counter volatile", "Make the counter private", "Call Thread.yield() after each increment"]$o$, 'Use an AtomicInteger', $e$volatile gives visibility but not atomicity of count++, while AtomicInteger performs the read-modify-write atomically.$e$, 10, 3, now(), now()),
    ('389179dc-e480-5e62-8540-48698ba95c5c', '00000000-0000-0000-0000-00000b000002', $q$Which map is designed for safe concurrent access by many threads?$q$, 'MCQ', $o$["ConcurrentHashMap", "HashMap", "TreeMap", "LinkedHashMap"]$o$, 'ConcurrentHashMap', $e$ConcurrentHashMap supports concurrent reads and updates; HashMap, TreeMap and LinkedHashMap are not thread-safe.$e$, 10, 4, now(), now()),
    ('1df01ab9-b151-56c8-a614-dff5ea491dc1', '00000000-0000-0000-0000-00000b000002', $q$Why are immutable objects automatically safe to share between threads?$q$, 'MCQ', $o$["Their state cannot change after construction", "The JVM locks them automatically", "They are always stored on the stack", "They cannot be garbage collected"]$o$, 'Their state cannot change after construction', $e$Without mutation there is nothing to race on, so sharing an immutable object needs no synchronization.$e$, 10, 5, now(), now()),
    ('b55fdb1a-3e5b-57e0-bfc3-fca8550f41ea', '00000000-0000-0000-0000-00000b000003', $q$What is a race condition?$q$, 'MCQ', $o$["The result depends on the unpredictable timing of threads accessing shared state", "A thread that runs faster than another", "A compile-time error in multi-threaded code", "A thread that never terminates"]$o$, 'The result depends on the unpredictable timing of threads accessing shared state', $e$A race condition exists when correctness depends on the relative timing of operations on shared data.$e$, 10, 1, now(), now()),
    ('3d10f5f7-8ed5-551f-bace-039ebe4737b2', '00000000-0000-0000-0000-00000b000003', $q$Why is count++ on a shared int not thread-safe?$q$, 'MCQ', $o$["It is a read, an add and a write, and threads can interleave between them", "Integers are immutable", "The JVM forbids it", "It always throws an exception"]$o$, 'It is a read, an add and a write, and threads can interleave between them', $e$Two threads can both read the same value and both write value + 1, losing one update.$e$, 10, 2, now(), now()),
    ('5b4245d5-17a4-54c4-9bb4-ac5265e2a043', '00000000-0000-0000-0000-00000b000003', $q$What does this program print? (Lines are shown separated by " / ".)

public class Main {
    private static int count = 0;

    private static synchronized void increment() {
        count++;
    }

    public static void main(String[] args) throws Exception {
        Thread[] ts = new Thread[3];
        for (int i = 0; i < ts.length; i++) {
            ts[i] = new Thread(() -> {
                for (int j = 0; j < 500; j++) increment();
            });
            ts[i].start();
        }
        for (Thread t : ts) t.join();
        System.out.println(count);
    }
}
$q$, 'PREDICT_OUTPUT', $o$["1500", "Anything up to 1500", "500", "Compilation error"]$o$, '1500', $e$increment() is synchronized, so all 3 x 500 increments are applied.$e$, 10, 3, now(), now()),
    ('802f27eb-03c1-58ae-ac09-34d744cc32dc', '00000000-0000-0000-0000-00000b000003', $q$The code does: if (!map.containsKey(key)) { map.put(key, value); } from many threads. Which fix removes the check-then-act race?$q$, 'CHOOSE_APPROACH', $o$["Use ConcurrentHashMap.putIfAbsent(key, value)", "Call map.size() first", "Declare the map static", "Add a Thread.sleep(1) before put"]$o$, 'Use ConcurrentHashMap.putIfAbsent(key, value)', $e$putIfAbsent performs the check and the insert as one atomic operation.$e$, 10, 4, now(), now()),
    ('49735b36-1268-57c0-8749-edad88430fe6', '00000000-0000-0000-0000-00000b000003', $q$What does volatile guarantee for a shared field?$q$, 'MCQ', $o$["Visibility of writes to other threads, but not atomicity of compound actions", "Mutual exclusion for all code touching it", "Atomic count++", "That the field is stored in a register"]$o$, 'Visibility of writes to other threads, but not atomicity of compound actions', $e$volatile prevents stale reads but count++ on a volatile int is still a race.$e$, 10, 5, now(), now()),
    ('6856f361-76b0-51f8-8b99-ade3211027a0', '00000000-0000-0000-0000-00000b000004', $q$Which object does a non-static synchronized instance method lock?$q$, 'MCQ', $o$["this", "The Class object", "The current Thread", "No lock is taken"]$o$, 'this', $e$An instance synchronized method uses the monitor of the instance (this).$e$, 10, 1, now(), now()),
    ('b3127654-9476-5aa3-923b-333f41170253', '00000000-0000-0000-0000-00000b000004', $q$Which monitor does a static synchronized method lock?$q$, 'MCQ', $o$["The Class object", "this", "A new lock per call", "Nothing"]$o$, 'The Class object', $e$Static synchronized methods lock on the Class object, e.g. Main.class.$e$, 10, 2, now(), now()),
    ('f3f23f6c-09d5-5966-968c-75769a3ddf29', '00000000-0000-0000-0000-00000b000004', $q$What does this program print? (Lines are shown separated by " / ".)

public class Main {
    public static void main(String[] args) throws Exception {
        Object lock = new Object();
