INSERT INTO coding_challenges (id, concept_id, title, description, difficulty, language, input_description, output_description, constraints, starter_code, solution_code, test_cases, time_limit_ms, memory_limit_mb, created_at, updated_at) VALUES
    ('00000000-0000-0000-0000-00000c000001', '00000000-0000-0000-0000-000000001011', 'Parallel Sum with Threads', $d$Split an array into four chunks and sum each chunk in its own thread. The main thread must wait for every worker to finish (join) before it adds up the partial sums and prints the total.$d$, 'EASY', 'JAVA', $i$Line 1: n. Line 2: n integers.$i$, $p$A single integer: the sum of all numbers.$p$, $k$1 <= n <= 5000, |a[i]| <= 1000. Use exactly four worker threads.$k$,
     $s$import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        long[] a = new long[n];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) a[i] = Long.parseLong(st.nextToken());

        int threads = 4;
        long[] partial = new long[threads];
        int chunk = (n + threads - 1) / threads;
        for (int t = 0; t < threads; t++) {
            final int id = t;
            final int from = Math.min(n, t * chunk);
            final int to = Math.min(n, from + chunk);
            new Thread(() -> {
                long s = 0;
                for (int i = from; i < to; i++) s += a[i];
                partial[id] = s;
            }).start();
        }

        long total = 0;
        for (long p : partial) total += p;
        System.out.println(total);
    }
}
$s$,
     $c$import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        long[] a = new long[n];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) a[i] = Long.parseLong(st.nextToken());

        int threads = 4;
        long[] partial = new long[threads];
        Thread[] workers = new Thread[threads];
        int chunk = (n + threads - 1) / threads;
        for (int t = 0; t < threads; t++) {
            final int id = t;
            final int from = Math.min(n, t * chunk);
            final int to = Math.min(n, from + chunk);
            workers[t] = new Thread(() -> {
                long s = 0;
                for (int i = from; i < to; i++) s += a[i];
                partial[id] = s;
            });
            workers[t].start();
        }
        for (Thread w : workers) w.join();

        long total = 0;
        for (long p : partial) total += p;
        System.out.println(total);
    }
}
