    ('00000000-0000-0000-0000-00000c000003', '00000000-0000-0000-0000-000000001012', 'Shared Results List', $d$n worker threads each add i*i (their own number, 1..n) to ONE shared list. A plain ArrayList is not safe for concurrent writers: elements get lost or the program crashes. Make the shared list safe, join all workers, then print the list size and the sum of its elements.$d$, 'MEDIUM', 'JAVA', $i$One line: n (number of worker threads).$i$, $p$One line: "<size> <sum>".$p$, $k$1 <= n <= 2000.$k$,
     $s$import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();

        List<Long> results = new ArrayList<>();
        Thread[] workers = new Thread[n];
        for (int i = 1; i <= n; i++) {
            final long value = (long) i * i;
            workers[i - 1] = new Thread(() -> results.add(value));
            workers[i - 1].start();
        }
        for (Thread w : workers) w.join();

        long sum = 0;
        for (long v : results) sum += v;
        System.out.println(results.size() + " " + sum);
    }
}
