     $c$import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();

        List<Long> results = Collections.synchronizedList(new ArrayList<>());
        Thread[] workers = new Thread[n];
        for (int i = 1; i <= n; i++) {
            final long value = (long) i * i;
            workers[i - 1] = new Thread(() -> results.add(value));
            workers[i - 1].start();
        }
        for (Thread w : workers) w.join();

        long sum = 0;
        synchronized (results) {
            for (long v : results) sum += v;
        }
        System.out.println(results.size() + " " + sum);
    }
}
