    ('00000000-0000-0000-0000-00000c000004', '00000000-0000-0000-0000-000000001013', 'Bounded Buffer Producer-Consumer', $d$A producer thread puts the numbers 1..n into a bounded buffer and a consumer thread takes them out. put() must block while the buffer is full and take() must block while it is empty (use wait/notifyAll inside a while loop). The consumer prints "Consumed: i" for every item in order, and main prints the total once both threads finish.$d$, 'HARD', 'JAVA', $i$One line: "capacity n" (buffer capacity, number of items).$i$, $p$n lines "Consumed: i" for i = 1..n, then a final line "Total: S" where S is the sum of 1..n.$p$, $k$1 <= capacity <= 50, 1 <= n <= 1000.$k$,
     $s$import java.util.*;

public class Main {
    static class BoundedBuffer {
        private final Queue<Integer> queue = new LinkedList<>();
        private final int capacity;

        BoundedBuffer(int capacity) {
            this.capacity = capacity;
        }

        public void put(int value) throws InterruptedException {
            queue.add(value);
        }

        public int take() throws InterruptedException {
            return queue.poll();
        }
    }

    public static void main(String[] args) throws Exception {
        Scanner in = new Scanner(System.in);
        int capacity = in.nextInt();
        int n = in.nextInt();
        BoundedBuffer buffer = new BoundedBuffer(capacity);
        StringBuilder out = new StringBuilder();
        long[] total = new long[1];

        Thread producer = new Thread(() -> {
            try {
                for (int i = 1; i <= n; i++) buffer.put(i);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });
        Thread consumer = new Thread(() -> {
            try {
                for (int i = 1; i <= n; i++) {
                    int v = buffer.take();
                    out.append("Consumed: ").append(v).append("\n");
                    total[0] += v;
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });
        producer.start();
        consumer.start();
        producer.join();
        consumer.join();
        System.out.print(out);
        System.out.println("Total: " + total[0]);
    }
}
$s$,
     $c$import java.util.*;

public class Main {
    static class BoundedBuffer {
        private final Queue<Integer> queue = new LinkedList<>();
        private final int capacity;

        BoundedBuffer(int capacity) {
            this.capacity = capacity;
        }

        public synchronized void put(int value) throws InterruptedException {
            while (queue.size() == capacity) {
                wait();
            }
            queue.add(value);
            notifyAll();
        }

        public synchronized int take() throws InterruptedException {
            while (queue.isEmpty()) {
                wait();
            }
            int value = queue.poll();
            notifyAll();
            return value;
        }
    }

    public static void main(String[] args) throws Exception {
        Scanner in = new Scanner(System.in);
        int capacity = in.nextInt();
        int n = in.nextInt();
        BoundedBuffer buffer = new BoundedBuffer(capacity);
        StringBuilder out = new StringBuilder();
        long[] total = new long[1];

        Thread producer = new Thread(() -> {
            try {
                for (int i = 1; i <= n; i++) buffer.put(i);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });
        Thread consumer = new Thread(() -> {
            try {
                for (int i = 1; i <= n; i++) {
                    int v = buffer.take();
                    out.append("Consumed: ").append(v).append("\n");
                    total[0] += v;
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });
        producer.start();
        consumer.start();
        producer.join();
        consumer.join();
        System.out.print(out);
        System.out.println("Total: " + total[0]);
    }
}
