    ('00000000-0000-0000-0000-00000c000005', '00000000-0000-0000-0000-000000001014', 'Ticket Seller with ReentrantLock', $d$Several seller threads keep selling tickets until none are left. The check "are there tickets left?" and the decrement must happen as one atomic step, otherwise tickets are oversold. Guard the critical section with a ReentrantLock (always unlock in finally). Print how many tickets were sold and how many remain.$d$, 'MEDIUM', 'JAVA', $i$One line: "T S" (tickets, sellers).$i$, $p$Two lines: "Sold: <number sold>" and "Remaining: <tickets left>".$p$, $k$1 <= T <= 100000, 1 <= S <= 16.$k$,
     $s$import java.util.*;

public class Main {
    private static int tickets;
    private static int sold = 0;

    private static boolean sellOne() {
        if (tickets > 0) {
            Thread.yield();
            tickets--;
            sold++;
            return true;
        }
        return false;
    }

    public static void main(String[] args) throws Exception {
        Scanner in = new Scanner(System.in);
        tickets = in.nextInt();
        int sellers = in.nextInt();

        Thread[] workers = new Thread[sellers];
        for (int i = 0; i < sellers; i++) {
            workers[i] = new Thread(() -> {
                while (sellOne()) {
                    // keep selling
                }
            });
            workers[i].start();
        }
        for (Thread w : workers) w.join();

        System.out.println("Sold: " + sold);
        System.out.println("Remaining: " + tickets);
    }
}
$s$,
     $c$import java.util.*;
import java.util.concurrent.locks.ReentrantLock;

public class Main {
    private static int tickets;
    private static int sold = 0;
    private static final ReentrantLock lock = new ReentrantLock();

    private static boolean sellOne() {
        lock.lock();
        try {
            if (tickets > 0) {
                Thread.yield();
                tickets--;
                sold++;
                return true;
            }
            return false;
        } finally {
            lock.unlock();
        }
    }

    public static void main(String[] args) throws Exception {
        Scanner in = new Scanner(System.in);
        tickets = in.nextInt();
        int sellers = in.nextInt();

        Thread[] workers = new Thread[sellers];
        for (int i = 0; i < sellers; i++) {
            workers[i] = new Thread(() -> {
                while (sellOne()) {
                    // keep selling
                }
            });
            workers[i].start();
        }
        for (Thread w : workers) w.join();

        System.out.println("Sold: " + sold);
        System.out.println("Remaining: " + tickets);
    }
}
