    ('00000000-0000-0000-0000-00000c000006', '00000000-0000-0000-0000-000000001015', 'Deadlock-Free Account Transfers', $d$Every transfer runs in its own thread and locks both accounts. When two transfers move money in opposite directions (0->1 and 1->0) and each locks "from" first, they wait for each other forever. Fix it by always locking the account with the smaller id first. After all transfers finish print every balance (balances may go negative; there is no overdraft check).$d$, 'HARD', 'JAVA', $i$Line 1: "k B t" (accounts, starting balance of each, transfers). Then t lines "from to amount".$i$, $p$One line with the k final balances separated by spaces.$p$, $k$1 <= k <= 10, 1 <= t <= 50, 0 <= from, to < k, 1 <= amount <= 1000.$k$,
     $s$import java.io.*;
import java.util.*;

public class Main {
    static class Account {
        final int id;
        long balance;

        Account(int id, long balance) {
            this.id = id;
            this.balance = balance;
        }
    }

    static void transfer(Account from, Account to, long amount) throws InterruptedException {
        synchronized (from) {
            Thread.sleep(2);
            synchronized (to) {
                from.balance -= amount;
                to.balance += amount;
            }
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer head = new StringTokenizer(br.readLine());
        int k = Integer.parseInt(head.nextToken());
        long start = Long.parseLong(head.nextToken());
        int t = Integer.parseInt(head.nextToken());

        Account[] accounts = new Account[k];
        for (int i = 0; i < k; i++) accounts[i] = new Account(i, start);

        Thread[] workers = new Thread[t];
        for (int i = 0; i < t; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            final Account from = accounts[Integer.parseInt(st.nextToken())];
            final Account to = accounts[Integer.parseInt(st.nextToken())];
            final long amount = Long.parseLong(st.nextToken());
            workers[i] = new Thread(() -> {
                try {
                    transfer(from, to, amount);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            });
            workers[i].start();
        }
        for (Thread w : workers) w.join();

        StringBuilder out = new StringBuilder();
        for (int i = 0; i < k; i++) {
            if (i > 0) out.append(' ');
