    ('00000000-0000-0000-0000-00000c000008', '00000000-0000-0000-0000-000000001008', 'First Occurrence in a Sorted Array', $d$The sorted array may contain duplicates. Print the index of the FIRST occurrence of the target, or -1 if it is absent. A plain binary search that stops at any match is not enough: keep searching to the left after a hit.$d$, 'MEDIUM', 'JAVA', $i$Line 1: n. Line 2: n sorted integers (duplicates allowed). Line 3: the target.$i$, $p$The smallest index i with a[i] == target, or -1.$p$, $k$1 <= n <= 5000.$k$,
     $s$import java.io.*;
import java.util.*;

public class Main {
    static int firstIndex(int[] a, int target) {
        // Return the FIRST index of target in the sorted array a, or -1 if it is absent.
        return -1;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        int[] a = new int[n];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) a[i] = Integer.parseInt(st.nextToken());
        int target = Integer.parseInt(br.readLine().trim());
        System.out.println(firstIndex(a, target));
    }
}
$s$,
     $c$import java.io.*;
import java.util.*;

public class Main {
    static int firstIndex(int[] a, int target) {
        int lo = 0, hi = a.length - 1, answer = -1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (a[mid] == target) {
                answer = mid;
                hi = mid - 1;
            } else if (a[mid] < target) {
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return answer;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        int[] a = new int[n];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) a[i] = Integer.parseInt(st.nextToken());
        int target = Integer.parseInt(br.readLine().trim());
        System.out.println(firstIndex(a, target));
    }
}
