    ('00000000-0000-0000-0000-00000c000009', '00000000-0000-0000-0000-000000001006', 'Rotate Array to the Right', $d$Rotate the array to the right by k positions (the last k elements move to the front, order preserved) and print the result on one line.$d$, 'EASY', 'JAVA', $i$Line 1: "n k". Line 2: n integers.$i$, $p$The rotated array, values separated by single spaces.$p$, $k$1 <= n <= 3000, 0 <= k <= 10^9.$k$,
     $s$import java.io.*;
import java.util.*;

public class Main {
    static int[] rotate(int[] a, int k) {
        // Return a new array rotated right by k positions.
        return a;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer head = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(head.nextToken());
        int k = Integer.parseInt(head.nextToken());
        int[] a = new int[n];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) a[i] = Integer.parseInt(st.nextToken());
        int[] r = rotate(a, k);
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < r.length; i++) {
            if (i > 0) out.append(' ');
            out.append(r[i]);
        }
        System.out.println(out);
    }
}
$s$,
     $c$import java.io.*;
import java.util.*;

public class Main {
    static int[] rotate(int[] a, int k) {
        int n = a.length;
        int shift = k % n;
        int[] r = new int[n];
        for (int i = 0; i < n; i++) {
            r[(i + shift) % n] = a[i];
        }
        return r;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer head = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(head.nextToken());
        int k = Integer.parseInt(head.nextToken());
        int[] a = new int[n];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) a[i] = Integer.parseInt(st.nextToken());
        int[] r = rotate(a, k);
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < r.length; i++) {
            if (i > 0) out.append(' ');
            out.append(r[i]);
        }
        System.out.println(out);
    }
}
