    ('00000000-0000-0000-0000-00000c000010', '00000000-0000-0000-0000-000000001006', 'Maximum Subarray Sum', $d$Find the largest sum of any non-empty contiguous subarray. Traverse the array once, tracking the best sum ending at the current index (Kadane).$d$, 'MEDIUM', 'JAVA', $i$Line 1: n. Line 2: n integers (may be negative).$i$, $p$One integer: the maximum subarray sum.$p$, $k$1 <= n <= 5000, |a[i]| <= 10^4.$k$,
     $s$import java.io.*;
import java.util.*;

public class Main {
    static long maxSubarray(int[] a) {
        // Return the maximum sum of a non-empty contiguous subarray.
        return 0;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        int[] a = new int[n];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) a[i] = Integer.parseInt(st.nextToken());
        System.out.println(maxSubarray(a));
    }
}
$s$,
     $c$import java.io.*;
import java.util.*;

public class Main {
    static long maxSubarray(int[] a) {
        long best = a[0];
        long current = a[0];
        for (int i = 1; i < a.length; i++) {
            current = Math.max(a[i], current + a[i]);
            best = Math.max(best, current);
        }
        return best;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        int[] a = new int[n];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) a[i] = Integer.parseInt(st.nextToken());
        System.out.println(maxSubarray(a));
    }
}
